<template><Card class="s45-manager"><template v-if="!$route.params.id"><h2>分账规则</h2><p class="intro">复用原合作协议、规则版本与维护权限。规则变更仅影响批准范围内的新交易；历史订单保留付款时规则。</p><RecordList endpoint="/rules" :searchable="false" :dated="false" :columns="columns" @open="open"/></template><template v-else><Button @click="back">返回规则列表</Button><Button :loading="loading" @click="load">重新读取</Button><Alert v-if="error" type="error">{{error}}</Alert><template v-if="detail"><h2>{{detail.current.payload.name}}</h2><Alert type="info" show-icon>{{detail.policy}}</Alert><section class="detail-section"><h3>当前规则及协议关联</h3><dl class="facts"><div v-for="row in facts" :key="row[0]" class="fact"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></div></dl><p>{{detail.current.payload.commissionClause}}</p><p class="meta">只有商品款计佣，固定履约费不计佣。0 基点是有效值；缺少费率、协议或版本的历史订单进入异常。</p></section><h3>同一规则历史版本</h3><div class="table-scroll"><Table :columns="columns" :data="detail.versions"/></div><p class="meta">原订单资金详情独立显示历史规则、实际资金和退款后测算。当前规则不用于补造旧订单资金事实。</p></template></template></Card></template>
<script>
import RecordList from './components/RecordList.vue';import {s45Read} from '@/api/stage45';import {managerSession} from '@/libs/manager-session';import {label,date,percent} from './presentation.cjs';
const columns=[{title:'规则名称',minWidth:220,render:(h,{row})=>h('span',row.payload.name)},{title:'店铺编号',key:'storeId',minWidth:180},{title:'版本',key:'revision',minWidth:90},{title:'历史费率',minWidth:120,render:(h,{row})=>h('span',percent(row.payload.rateBps))},{title:'状态',minWidth:120,render:(h,{row})=>h('span',label(row.status))},{title:'生效时间',minWidth:190,render:(h,{row})=>h('span',date(row.actualFrom))}];
export default{components:{RecordList},data(){return{columns,detail:null,loading:false,error:'',ticket:0}},computed:{facts(){const c=this.detail.current;return [['规则编号 / 版本',c.id+' / '+c.revision],['店铺编号',c.storeId],['协议编号 / 版本',c.agreementId+' / '+c.agreementRevision],['商品款费率',percent(c.payload.rateBps)],['生效开始',date(c.actualFrom)],['生效截止',date(c.actualTo)],['规则状态',label(c.status)],['执行触发条件','真实完成且无阻断售后']]}},watch:{'$route.params.id':{handler(){this.detail=null;if(this.$route.params.id)this.load()},immediate:true}},beforeDestroy(){this.ticket++;this.detail=null},methods:{open(row){this.$router.push({path:'/s45/rules/'+row.id,query:this.$route.query})},back(){this.$router.push({path:'/s45/rules',query:this.$route.query})},async load(){const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const v=await s45Read('/rules/'+this.$route.params.id);if(ticket===this.ticket&&managerSession.sameSession(owner))this.detail=v}catch(e){if(ticket===this.ticket){this.detail=null;this.error=e.message}}finally{if(ticket===this.ticket)this.loading=false}}}};
</script><style lang="scss">@import './stage45.scss';</style>
